package com.nexus.event;
import com.nexus.data.NoticeRepository; import com.nexus.domain.Notice; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.stereotype.Component; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.*;
/** Outbox delivery after the incident transaction. Restricted test recipient; never sends private content. */
@Component public class EmailWorker{
 private final NoticeRepository repo;private final ObjectMapper mapper;private final boolean enabled;private final String key,from,to;private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();
 public EmailWorker(NoticeRepository r,ObjectMapper m,@Value("${nexus.email.enabled}") boolean enabled,@Value("${nexus.email.key}") String key,@Value("${nexus.email.from}") String from,@Value("${nexus.email.recipient}") String to){repo=r;mapper=m;this.enabled=enabled;this.key=key;this.from=from;this.to=to;}
 @Scheduled(fixedDelay=30000) public void send(){if(!enabled)return;for(Notice n:repo.findTop30ByDeliveryOrderByIdAsc("PENDING")){if(key.isBlank()||from.isBlank()||to.isBlank()){n.delivery="FAILED";repo.save(n);continue;}try{String body=mapper.writeValueAsString(Map.of("from",from,"to",List.of(to),"subject","NEXUS test notification","text",n.message));var request=HttpRequest.newBuilder(URI.create("https://api.resend.com/emails")).timeout(Duration.ofSeconds(8)).header("Authorization","Bearer "+key).header("Content-Type","application/json").header("Idempotency-Key","nexus-notice-"+n.id).POST(HttpRequest.BodyPublishers.ofString(body)).build();var response=client.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()/100==2){n.delivery="SENT";n.providerId=mapper.readTree(response.body()).path("id").asText();}else n.delivery="FAILED";}catch(InterruptedException ex){Thread.currentThread().interrupt();return;}catch(Exception ex){n.delivery="FAILED";}repo.save(n);}}
}
